module.exports = function(RED) {
    "use strict";

    function SocialService2Node(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        
        this.socialResource = n.socialResource;
        this.socialResourceLabel = n.socialResourceLabel;
        this.func = n.func;

        this.params = [];

        if (n.nodeParams) {
            try {
                if (typeof n.nodeParams === 'string') {
                    // 如果是字符串，尝试解析
                    this.params = JSON.parse(n.nodeParams);
                } else if (Array.isArray(n.nodeParams)) {
                    // 如果已经是数组（编辑器可能自动转换了），直接赋值
                    this.params = n.nodeParams;
                } else {
                    // 如果是其他对象，尝试转换或保留为空
                    this.params = [n.nodeParams];
                }
            } catch (err) {
                node.error("解析参数列表失败: " + err);
                this.params = [];
            }
        }

        this.on("input", function(msg, send, done) {
            
            msg.socialResource = node.socialResource;
            msg.socialResourceLabel = node.socialResourceLabel;
            msg.func = node.func; // 这里就是 url
            msg.params = node.params;
            
            send(msg);
            if (done) {
                done();
            }
        });
    }

    RED.nodes.registerType("Social Service2", SocialService2Node);
};